        let state = Doc::new()
            .transact()
            .encode_state_as_update_v1(&StateVector::default());
        let bbox = crate::object::Bbox {
            min_x: 0.0,
            min_y: 0.0,
            max_x: 1.0,
            max_y: 1.0,
        };
        let record = TileRecord {
            coord,
            doc_state: state,
            updated_at: 0,
            objects: (0..objects)
                .map(|i| (format!("o{i}"), bbox.clone()))
                .collect(),
        };
        store.rows.borrow_mut().insert(coord, record);
    }

