import { readFileSync } from "node:fs";
import { homedir } from "node:os";

const sha = process.argv[2];
const env = Object.fromEntries(
  readFileSync(`${homedir()}/.config/stallion/cf-env`, "utf8")
    .split("\n")
    .map((l) => l.replace(/^export\s+/, "").match(/^([A-Z_]+)=["']?(.*?)["']?$/))
    .filter(Boolean)
    .map((m) => [m[1], m[2]]),
);
const token = env.CLOUDFLARE_API_TOKEN;
const api = async (path) => {
  const r = await fetch(`https://api.cloudflare.com/client/v4${path}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  const body = await r.json();
  if (!body.success) throw new Error(`${path}: ${r.status} ${JSON.stringify(body.errors)}`);
  return body.result;
};
const account = env.CLOUDFLARE_ACCOUNT_ID ?? (await api("/accounts"))[0].id;
const scripts = await api(`/accounts/${account}/workers/scripts`);
const script = scripts.find((s) => s.id === "stallion");
const tag = script.tag;
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const deadline = Date.now() + 25 * 60 * 1000;
while (Date.now() < deadline) {
  const builds = await api(`/accounts/${account}/builds/workers/${tag}/builds?per_page=10`);
  const build = builds.find((b) => b.build_trigger_metadata?.commit_hash === sha);
  if (build) {
    console.log(`build ${build.build_uuid} status=${build.status} outcome=${build.build_outcome}`);
    if (build.status === "stopped") process.exit(build.build_outcome === "success" ? 0 : 1);
  } else console.log("no build for sha yet");
  sleep(30000);
}
console.log("timed out");
process.exit(2);
EOF
