const url = `${ORIGIN}/b/${boardId}`;
const device = devices["Galaxy Tab S9"];
const { width: W, height: H } = device.viewport;
const DPR = device.deviceScaleFactor;
const PAPER = [0xfb, 0xfa, 0xf7];
const INK = [0x1f, 0x23, 0x28];
const GREY = [0x8c, 0x8c, 0x8c];
const blend = (c) => c.map((x, i) => Math.round(0.7 * x + 0.3 * PAPER[i]));
const problems = [];

const browser = await chromium.launch({ headless: true });
const context = (camera) =>
  browser.newContext({ ...device, colorScheme: "light", extraHTTPHeaders: accessHeaders() }).then(async (ctx) => {
    if (camera) {
      await ctx.addInitScript(
        ([key, value]) => localStorage.setItem(key, value),
        [`stallion:camera:${boardId}`, JSON.stringify(camera)],
      );
    }
    const page = await ctx.newPage();
    page.on("console", (m) => {
      if (m.type() === "error" && !/favicon/.test(`${m.text()} ${m.location().url}`)) problems.push(m.text());
    });
    page.on("pageerror", (e) => problems.push(`pageerror ${e.message}`));
    return { ctx, page };
  });

const ready = async (page) => {
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
  await page.getByText("Connected").first().waitFor({ timeout: 20000 });
  await page.waitForTimeout(2500);
};

const pixels = async (page, name) => {
  const path = join(DIR, `${name}.png`);
  await page.screenshot({ path });
  const data = await page.evaluate(() => {
    const c = document.querySelector("canvas.surface");
    const ctx = c.getContext("2d");
    return { w: c.width, h: c.height, d: Array.from(ctx.getImageData(0, 0, c.width, c.height).data) };
  });
  return { path, ...data };
};

const near = (a, b, tol) => a.every((x, i) => Math.abs(x - b[i]) <= tol);
const findAround = (img, cx, cy, radius, want) => {
  const hits = [];
  for (let y = Math.floor(cy - radius); y <= cy + radius; y++)
    for (let x = Math.floor(cx - radius); x <= cx + radius; x++) {
      const i = (y * img.w + x) * 4;
      const px = [img.d[i], img.d[i + 1], img.d[i + 2]];
      if (near(px, want, 12)) hits.push({ x, y, px });
    }
