  for (const p of pts.slice(1)) await touch("touchMove", p);
  await touch("touchEnd");
  await a.page.waitForTimeout(3000);
  await a.page.screenshot({ path: join(DIR, "1-drawn.png") });
  const stored = await a.page.evaluate(
    () =>
      new Promise((resolve, reject) => {
        const r = indexedDB.open("stallion");
        r.onerror = () => reject(r.error);
        r.onsuccess = () => {
          const q = r.result.transaction("objects").objectStore("objects").getAll();
          q.onsuccess = () => resolve(q.result.map((o) => ({ level: o.level, tx: o.tx, ty: o.ty, keys: Object.keys(o) })));
        };
      }),
  );
  console.log("stored", JSON.stringify(stored));
  const level = stored[0].level;
  await a.ctx.close();
  await new Promise((r) => setTimeout(r, 7000));

  const cx = 211;
  const cy = 410;
  const z1 = 1 / 48;
  const b = await context({ x: cx - W / 2 / z1, y: cy - H / 2 / z1, zoom: z1 });
  await ready(b.page);
  const img1 = await pixels(b.page, "2-marker");
  const ink = findAround(img1, (W / 2) * DPR, (H / 2) * DPR, 8, blend(INK));
  console.log(`marker zoom 1/48: ink-blend hits ${ink.length} ${JSON.stringify(ink.slice(0, 4))}, non-paper px ${nonPaper(img1)}`);
  await b.ctx.close();

  const size = 256 * 2 ** level;
  const tile = { tx: Math.floor(cx / size), ty: Math.floor(cy / size) };
  const hx = (tile.tx + 0.5) * size;
  const hy = (tile.ty + 0.5) * size;
  const z2 = 0.75 / size;
  const c = await context({ x: hx - W / 2 / z2, y: hy - H / 2 / z2, zoom: z2 });
  await ready(c.page);
  const img2 = await pixels(c.page, "3-hint");
  const grey = findAround(img2, (W / 2) * DPR, (H / 2) * DPR, 8, blend(GREY));
  const inkHere = findAround(img2, (W / 2) * DPR, (H / 2) * DPR, 8, blend(INK));
  console.log(`hint zoom ${z2}: level ${level} tile ${JSON.stringify(tile)} grey hits ${grey.length} ${JSON.stringify(grey.slice(0, 4))}, ink hits ${inkHere.length}, non-paper px ${nonPaper(img2)}`);
  await c.ctx.close();
} finally {
  await browser.close();
  console.log(`board ${url}`);
  console.log(`console errors ${problems.length}: ${JSON.stringify(problems)}`);
}
